#!/usr/bin/env python3
# Conall's course, reworked from your playtest. Against theButterfly 1e67861.
#
#   python3 course_rework_patch.py          (from the repo root)
#   then edit tools/dialogue/drafts/faicheCourse.dlg as you like, and
#   node tools/dialogue/course.mjs tools/dialogue/drafts/faicheCourse.dlg
#
# The new order: meet, space, sword, calls, fatigue, strong, dummy, feet,
# drag, duel (the finale), end. See the top of faicheCourse.js.
#
# Also, everywhere: a caption clears before a dialogue card comes up; and each
# speaker's Irish is one colour in cards and captions alike (ui/speakers.js:
# Conall green, Uathach amber, the narrator pale blue-white).
#
# Whole files are written. Idempotent; a file changed since the patch was made
# is skipped (rerun with --force to overwrite it).
import base64, hashlib, os, sys, zlib

FILES = [
    ('js/game/combat/melee.js', ['6b01a583d0453e596b5336ff73417dcb7cdc0599f20bb8124138adc9b09c9df4'], '2aae744d46a270676d5e50f6aea88fac285cf54a01137fa77b4d447244ebb3ff',
     ''),
    ('js/game/scenes/locations/skye/courseLines.js', ['9601867d45afd6706aca051dc67a3e5d534349a90a31851ba0a7be01eab81b22'], 'f415c47a9c9c780697d2e00f25f2a96d0c756dc32877408ccbf33c1bf6e079f6',
     ''),
    ('js/game/scenes/locations/skye/courseScript.js', ['244528f1eb7c9e7aed82bf1266e3ae2a326028b4b9980aba0d7fd7b145501c31'], '6b492783ddda7470da133e04f0c266cf97ef4cc0c10286a7d7d4476c51d3e17c',
     ''),
    ('js/game/scenes/locations/skye/faicheCourse.js', ['62883153ec53f87df6092092772abc232a661fb0514dc3ca55f5aaaf79ca498e'], '651150a631a73f165dbb57ebd16b34182119e7cfc473b2ed49820fd75e3bfe3c',
     ''),
    ('js/game/scenes/locations/skye/faicheLesson.js', ['1836992d5a983963d0dcfd44c5d8d42c59f96fbe6aa853056ea071541070814b'], '961988b4df7bbc6f37d6f05c34552d5c2dcf522871a21a3b422b299c146cca58',
     ''),
    ('js/game/scenes/locations/skye/faicheTournament.js', ['2f75f91adced0e4cba3c008ef1397b4edec817a3f79392930db2cbed2743f53c'], '67d3dfb30ff8b03a42281cbb3cd0e26564054365a78f71e09eea993da88ecb6c',
     ''),
    ('js/game/scenes/locations/skye/landfall.js', ['5beeb5d5c7d0a0282ab37479450683faa412ff075bb6c5019d545dbeab9e4489'], '8c072a21739606e97882f65cc2e1ec37800e3a2dddc63c845d641b07323bad31',
     ''),
    ('js/game/scenes/locations/skye/skyeCaption.js', ['f38d56da6f3aae3642cdad50a7e837c48541600cf5d0c6b25f9fa362822536ec'], 'e66a33ffff42524dc94d5548bebd593bf8a5928789f896e8f5f62709cc1229a4',
     ''),
    ('js/game/scenes/locations/skye/skyeCladach.js', ['f4e83ed3ffd723bc360ca90c73fd808e492ba407391c37c1c9dcfdac82c0668d'], '3d7ba59a70168a26079b7d2d0c1c41c60d594998dccde56df786953c829d4f38',
     ''),
    ('js/game/ui/encounterPanel.js', ['8dc916656527500668526e1a3d1613f9ac89b82d6396eca17a843345a1980c9b'], 'fc0e2c08bf61d87a89ac950d913771bbfc5a71073c9d01235c42d94874524f81',
     ''),
    ('js/game/ui/speakers.js', [], '13baae23ac1498e94d0fdacb53799b7ede45ce0a07226ff369c3149bb859dcb9',
     ''),
    ('js/game/ui/textPanel.js', ['0ec355b9716e9f8eabcb3ea341fb3b99d9bfbe5fbbf17e8823f685b1f175ba4c'], 'f72f3ce26fc1424a3248756e818ff4bbcf227aadff7399b94096dbf02e888849',
     ''),
    ('tools/dialogue/drafts/faicheCourse.dlg', ['5bdc3f9072b7683597f0e67b224baa9785565a2336b932f3e0ecbbd040121964'], 'ae36fdcab48dead10a281284753f0d40f4bb7b6ce64fc742310d04b83d12e773',
     ''),
]

force = '--force' in sys.argv
sha = lambda b: hashlib.sha256(b).hexdigest()
bad = False
for path, old_shas, new_sha, blob in FILES:
    if os.path.exists(path):
        cur = sha(open(path, 'rb').read())
        if cur == new_sha:
            print('already applied:', path); continue
        if cur not in old_shas and not force:
            print('CHANGED SINCE THE PATCH WAS MADE, skipped:', path); bad = True; continue
    elif old_shas and not force:
        print('missing:', path, '(run from the repo root)'); bad = True; continue
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    open(path, 'wb').write(zlib.decompress(base64.b64decode(blob)))
    print('patched:', path)
sys.exit(1 if bad else 0)
